'use server';

import { updateTag } from 'next/cache';

export async function createPost(formData: FormData) {
  const title = formData.get('title') as string;
  const body = formData.get('body') as string;

  const response = await fetch('https://jsonplaceholder.typicode.com/posts', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title, body, userId: 1 }),
  });

  if (!response.ok) {
    throw new Error('Failed to create post');
  }

  // updateTag immediately expires the cache entry for the "posts" tag.
  // Unlike revalidateTag, it does not use a stale-while-revalidate strategy —
  // the next page load will block until fresh data is fetched from the source.
  updateTag('posts');
}

